t.script:
document.addEventListener("DOMContentLoaded", function () {

    const form = document.getElementById("lr_form");

    const tipoDocumento = document.getElementById("lr_tipo_documento");
    const numeroDocumento = document.getElementById("lr_numero_documento");
    const nombreConsumidor = document.getElementById("lr_nombre_consumidor");
    const nombreLabel = document.getElementById("lr_nombre_label");
    const domicilioConsumidor = document.getElementById("lr_domicilio_consumidor");
    const telefono = document.getElementById("lr_telefono");
    const email = document.getElementById("lr_email");

    const tipoBien = document.getElementById("lr_tipo_bien");
    const monto = document.getElementById("lr_monto");
    const descripcionBien = document.getElementById("lr_descripcion_bien");

    const tipoReclamacion = document.getElementById("lr_tipo_reclamacion");
    const detalle = document.getElementById("lr_detalle");
    const pedidoConsumidor = document.getElementById("lr_pedido_consumidor");

    const declaracion = document.getElementById("lr_declaracion");
    const privacidad = document.getElementById("lr_privacidad");

    const docStatus = document.getElementById("lr_doc_status");

    const currency = document.getElementById("lr_currency");
    const currencySymbol = document.getElementById("lr_currency_symbol");
    const currencyPicker = document.getElementById("lr_currency_picker");
    const currencyButton = document.getElementById("lr_currency_button");
    const currencyMenu = document.getElementById("lr_currency_menu");
    const currencyName = document.getElementById("lr_currency_name");
    const currencyCode = document.getElementById("lr_currency_code");
    const currencyFlag = currencyButton.querySelector(".lr-flag");
    const currencyOptions = currencyMenu.querySelectorAll(".lr-currency-option");

    const canvas = document.getElementById("lr_signature_canvas");
    const signatureData = document.getElementById("lr_signature_data");
    const clearSignature = document.getElementById("lr_clear_signature");
    const submitButton = document.getElementById("lr_submit");
    const ctx = canvas.getContext("2d");

    let drawing = false;
    let hasSignature = false;
    let dniTimer = null;
    let rucTimer = null;

    function getError(id) {
        return document.getElementById(id);
    }

    function setInvalid(field, errorElement, message) {
        if (field) {
            field.classList.add("is-invalid");
        }

        if (errorElement) {
            if (message) {
                errorElement.textContent = message;
            }

            errorElement.classList.add("show");
        }
    }

    function clearInvalid(field, errorElement) {
        if (field) {
            field.classList.remove("is-invalid");
        }

        if (errorElement) {
            errorElement.classList.remove("show");
        }
    }

    function normalizeText(value) {
        return (value || "").trim();
    }

    function isValidEmail(value) {
        const text = normalizeText(value);

        if (!text) {
            return false;
        }

        if (text.length > 180) {
            return false;
        }

        return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(text);
    }

    function isValidPhone(value) {
        const text = normalizeText(value);

        if (!text) {
            return false;
        }

        const digits = text.replace(/\D/g, "");

        return digits.length >= 6 && digits.length <= 15;
    }

    function validateDocument() {
        const type = tipoDocumento.value;
        const value = normalizeText(numeroDocumento.value);
        const error = getError("lr_doc_error");

        clearInvalid(numeroDocumento, error);

        if (!value) {
            setInvalid(
                numeroDocumento,
                error,
                "Ingrese el número de documento."
            );
            return false;
        }

        if (type === "dni") {
            if (!/^\d{8}$/.test(value)) {
                setInvalid(
                    numeroDocumento,
                    error,
                    "El DNI debe contener 8 dígitos."
                );
                return false;
            }
        }

        if (type === "ruc") {
            if (!/^\d{11}$/.test(value)) {
                setInvalid(
                    numeroDocumento,
                    error,
                    "El RUC debe contener 11 dígitos."
                );
                return false;
            }
        }

        if ((type === "ce" || type === "pasaporte") && value.length < 3) {
            setInvalid(
                numeroDocumento,
                error,
                "Ingrese un número de documento válido."
            );
            return false;
        }

        return true;
    }

    function validateRequiredText(field, errorId, message) {
        const error = getError(errorId);
        const value = normalizeText(field.value);

        clearInvalid(field, error);

        if (!value) {
            setInvalid(field, error, message);
            return false;
        }

        return true;
    }

    function validateSelect(field, errorId, message) {
        const error = getError(errorId);

        clearInvalid(field, error);

        if (!field.value) {
            setInvalid(field, error, message);
            return false;
        }

        return true;
    }

    function validateEmailField() {
        const error = getError("lr_email_error");
        const value = normalizeText(email.value);

        clearInvalid(email, error);

        if (!isValidEmail(value)) {
            setInvalid(
                email,
                error,
                "Ingrese un correo electrónico válido."
            );
            return false;
        }

        email.value = value.toLowerCase();

        return true;
    }

    function validatePhoneField() {
        const error = getError("lr_telefono_error");

        clearInvalid(telefono, error);

        if (!isValidPhone(telefono.value)) {
            setInvalid(
                telefono,
                error,
                "Ingrese un teléfono válido."
            );
            return false;
        }

        return true;
    }

    function validateAmount() {
        const error = getError("lr_monto_error");

        clearInvalid(monto, error);

        if (!normalizeText(monto.value)) {
            return true;
        }

        const value = Number(monto.value);

        if (!Number.isFinite(value) || value < 0) {
            setInvalid(
                monto,
                error,
                "Ingrese un monto válido."
            );
            return false;
        }

        return true;
    }

    function validateCheckbox(field, errorId) {
        const error = getError(errorId);

        if (field.checked) {
            error.classList.remove("show");
            return true;
        }

        error.classList.add("show");
        return false;
    }

    function validateSignature() {
        const error = getError("lr_signature_error");

        if (hasSignature) {
            error.classList.remove("show");
            return true;
        }

        error.classList.add("show");
        return false;
    }

    function validateForm() {
        let valid = true;

        if (!validateDocument()) valid = false;

        if (!validateRequiredText(
            nombreConsumidor,
            "lr_nombre_error",
            tipoDocumento.value === "ruc"
                ? "Complete la razón social."
                : "Complete el nombre completo."
        )) valid = false;

        if (!validateRequiredText(
            domicilioConsumidor,
            "lr_domicilio_error",
            "Complete el domicilio."
        )) valid = false;

        if (!validatePhoneField()) valid = false;
        if (!validateEmailField()) valid = false;

        if (!validateSelect(
            tipoBien,
            "lr_tipo_bien_error",
            "Seleccione producto o servicio."
        )) valid = false;

        if (!validateAmount()) valid = false;

        if (!validateRequiredText(
            descripcionBien,
            "lr_descripcion_bien_error",
            "Complete la descripción."
        )) valid = false;

        if (!validateSelect(
            tipoReclamacion,
            "lr_tipo_reclamacion_error",
            "Seleccione reclamo o queja."
        )) valid = false;

        if (!validateRequiredText(
            detalle,
            "lr_detalle_error",
            "Complete el detalle."
        )) valid = false;

        if (!validateRequiredText(
            pedidoConsumidor,
            "lr_pedido_consumidor_error",
            "Complete el pedido del consumidor."
        )) valid = false;

        if (!validateSignature()) valid = false;

        if (!validateCheckbox(
            declaracion,
            "lr_declaracion_error"
        )) valid = false;

        if (!validateCheckbox(
            privacidad,
            "lr_privacidad_error"
        )) valid = false;

        return valid;
    }

    function focusFirstInvalid() {
        const firstInvalid = form.querySelector(".is-invalid");

        if (firstInvalid) {
            firstInvalid.scrollIntoView({
                behavior:"smooth",
                block:"center"
            });

            window.setTimeout(function () {
                firstInvalid.focus();
            }, 250);

            return;
        }

        const signatureError = getError("lr_signature_error");

        if (signatureError.classList.contains("show")) {
            canvas.scrollIntoView({
                behavior:"smooth",
                block:"center"
            });
        }
    }

    function resizeCanvas() {
        const ratio = Math.max(window.devicePixelRatio || 1, 1);
        const rect = canvas.getBoundingClientRect();
        const saved = hasSignature
            ? canvas.toDataURL("image/png")
            : null;

        canvas.width = Math.floor(rect.width * ratio);
        canvas.height = Math.floor(180 * ratio);

        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
        ctx.lineWidth = 2;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.strokeStyle = "#17233f";

        if (saved) {
            const image = new Image();

            image.onload = function () {
                ctx.drawImage(image, 0, 0, rect.width, 180);
            };

            image.src = saved;
        }
    }

    function point(event) {
        const rect = canvas.getBoundingClientRect();
        const source = event.touches
            ? event.touches[0]
            : event;

        return {
            x:source.clientX - rect.left,
            y:source.clientY - rect.top
        };
    }

    function start(event) {
        event.preventDefault();

        drawing = true;
        hasSignature = true;

        getError("lr_signature_error").classList.remove("show");

        const p = point(event);

        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
    }

    function move(event) {
        if (!drawing) {
            return;
        }

        event.preventDefault();

        const p = point(event);

        ctx.lineTo(p.x, p.y);
        ctx.stroke();
    }

    function end(event) {
        if (!drawing) {
            return;
        }

        event.preventDefault();
        drawing = false;
    }

    canvas.addEventListener("mousedown", start);
    canvas.addEventListener("mousemove", move);
    window.addEventListener("mouseup", end);

    canvas.addEventListener("touchstart", start, {
        passive:false
    });

    canvas.addEventListener("touchmove", move, {
        passive:false
    });

    canvas.addEventListener("touchend", end, {
        passive:false
    });

    clearSignature.addEventListener("click", function () {
        ctx.clearRect(
            0,
            0,
            canvas.width,
            canvas.height
        );

        hasSignature = false;
        signatureData.value = "";

        getError("lr_signature_error").classList.remove("show");
    });

    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    function updateDocumentMode() {
        const type = tipoDocumento.value;
        const isDni = type === "dni";
        const isRuc = type === "ruc";

        numeroDocumento.value = "";
        nombreConsumidor.value = "";
        nombreConsumidor.readOnly = false;

        docStatus.textContent = "";
        docStatus.className = "lr-help";

        clearInvalid(
            numeroDocumento,
            getError("lr_doc_error")
        );

        clearInvalid(
            nombreConsumidor,
            getError("lr_nombre_error")
        );

        if (isDni) {
            numeroDocumento.maxLength = 8;
            numeroDocumento.inputMode = "numeric";

            nombreLabel.innerHTML =
                'Nombre completo *';

        } else if (isRuc) {
            numeroDocumento.maxLength = 11;
            numeroDocumento.inputMode = "numeric";

            nombreLabel.innerHTML =
                'Razón social *';

        } else {
            numeroDocumento.maxLength = 20;
            numeroDocumento.inputMode = "text";

            nombreLabel.innerHTML =
                'Nombre completo *';
        }
    }

    async function lookupDni() {
        if (tipoDocumento.value !== "dni") {
            return;
        }

        const dni = numeroDocumento.value.replace(/\D/g, "");
        numeroDocumento.value = dni;

        if (dni.length !== 8) {
            docStatus.textContent = "";
            docStatus.className = "lr-help";
            nombreConsumidor.readOnly = false;
            return;
        }

        docStatus.textContent = "Consultando...";
        docStatus.className = "lr-help";

        try {
            const response = await fetch(
                "/libro-de-reclamaciones/consultar-dni",
                {
                    method:"POST",
                    headers:{
                        "Content-Type":"application/json"
                    },
                    body:JSON.stringify({
                        jsonrpc:"2.0",
                        method:"call",
                        params:{
                            numero:dni
                        },
                        id:Date.now()
                    })
                }
            );

            const payload = await response.json();
            const result = payload.result || {};

            if (result.ok) {
                nombreConsumidor.value = result.nombre || "";
                nombreConsumidor.readOnly = true;

                docStatus.textContent = "Documento verificado.";
                docStatus.className = "lr-help lr-help-success";

                clearInvalid(
                    numeroDocumento,
                    getError("lr_doc_error")
                );

                clearInvalid(
                    nombreConsumidor,
                    getError("lr_nombre_error")
                );

            } else {
                nombreConsumidor.readOnly = false;
                docStatus.textContent = "";
                docStatus.className = "lr-help";
            }

        } catch (error) {
            nombreConsumidor.readOnly = false;
            docStatus.textContent = "";
            docStatus.className = "lr-help";
        }
    }

    async function lookupRuc() {
        if (tipoDocumento.value !== "ruc") {
            return;
        }

        const ruc = numeroDocumento.value.replace(/\D/g, "");
        numeroDocumento.value = ruc;

        if (ruc.length !== 11) {
            nombreConsumidor.readOnly = false;
            return;
        }

        docStatus.textContent = "Consultando...";
        docStatus.className = "lr-help";

        try {
            const response = await fetch(
                "/libro-de-reclamaciones/consultar-ruc",
                {
                    method:"POST",
                    headers:{
                        "Content-Type":"application/json"
                    },
                    body:JSON.stringify({
                        jsonrpc:"2.0",
                        method:"call",
                        params:{
                            numero:ruc
                        },
                        id:Date.now()
                    })
                }
            );

            const payload = await response.json();
            const result = payload.result || {};

            if (result.ok) {
                nombreConsumidor.value =
                    result.razon_social ||
                    result.nombre ||
                    "";

                nombreConsumidor.readOnly = true;

                if (result.direccion) {
                    domicilioConsumidor.value =
                        result.direccion;
                }

                docStatus.textContent = "Documento verificado.";
                docStatus.className = "lr-help lr-help-success";

                clearInvalid(
                    numeroDocumento,
                    getError("lr_doc_error")
                );

                clearInvalid(
                    nombreConsumidor,
                    getError("lr_nombre_error")
                );

                if (result.direccion) {
                    clearInvalid(
                        domicilioConsumidor,
                        getError("lr_domicilio_error")
                    );
                }

            } else {
                nombreConsumidor.readOnly = false;
                docStatus.textContent = "";
                docStatus.className = "lr-help";
            }

        } catch (error) {
            nombreConsumidor.readOnly = false;
            docStatus.textContent = "";
            docStatus.className = "lr-help";
        }
    }

    tipoDocumento.addEventListener(
        "change",
        updateDocumentMode
    );

    numeroDocumento.addEventListener("input", function () {
        clearInvalid(
            numeroDocumento,
            getError("lr_doc_error")
        );

        docStatus.textContent = "";
        docStatus.className = "lr-help";

        if (tipoDocumento.value === "dni") {
            numeroDocumento.value =
                numeroDocumento.value
                    .replace(/\D/g, "")
                    .slice(0, 8);

            clearTimeout(dniTimer);

            dniTimer = setTimeout(
                lookupDni,
                400
            );

        } else if (tipoDocumento.value === "ruc") {
            numeroDocumento.value =
                numeroDocumento.value
                    .replace(/\D/g, "")
                    .slice(0, 11);

            clearTimeout(rucTimer);

            rucTimer = setTimeout(
                lookupRuc,
                400
            );
        }
    });

    numeroDocumento.addEventListener(
        "blur",
        validateDocument
    );

    nombreConsumidor.addEventListener("input", function () {
        clearInvalid(
            nombreConsumidor,
            getError("lr_nombre_error")
        );
    });

    domicilioConsumidor.addEventListener("input", function () {
        clearInvalid(
            domicilioConsumidor,
            getError("lr_domicilio_error")
        );
    });

    telefono.addEventListener("input", function () {
        clearInvalid(
            telefono,
            getError("lr_telefono_error")
        );
    });

    telefono.addEventListener(
        "blur",
        validatePhoneField
    );

    email.addEventListener("input", function () {
        clearInvalid(
            email,
            getError("lr_email_error")
        );
    });

    email.addEventListener(
        "blur",
        validateEmailField
    );

    tipoBien.addEventListener("change", function () {
        clearInvalid(
            tipoBien,
            getError("lr_tipo_bien_error")
        );
    });

    monto.addEventListener("input", function () {
        clearInvalid(
            monto,
            getError("lr_monto_error")
        );
    });

    monto.addEventListener(
        "blur",
        validateAmount
    );

    descripcionBien.addEventListener("input", function () {
        clearInvalid(
            descripcionBien,
            getError("lr_descripcion_bien_error")
        );
    });

    tipoReclamacion.addEventListener("change", function () {
        clearInvalid(
            tipoReclamacion,
            getError("lr_tipo_reclamacion_error")
        );
    });

    detalle.addEventListener("input", function () {
        clearInvalid(
            detalle,
            getError("lr_detalle_error")
        );
    });

    pedidoConsumidor.addEventListener("input", function () {
        clearInvalid(
            pedidoConsumidor,
            getError("lr_pedido_consumidor_error")
        );
    });

    declaracion.addEventListener("change", function () {
        if (declaracion.checked) {
            getError(
                "lr_declaracion_error"
            ).classList.remove("show");
        }
    });

    privacidad.addEventListener("change", function () {
        if (privacidad.checked) {
            getError(
                "lr_privacidad_error"
            ).classList.remove("show");
        }
    });

    function setCurrency(option) {
        const value = option.dataset.value;
        const symbol = option.dataset.symbol;
        const flag = option.dataset.flag;
        const name = option.dataset.name;

        currency.value = value;

        currencySymbol.textContent = symbol;
        currencyFlag.textContent = flag;
        currencyName.textContent = name;
        currencyCode.textContent = value;

        currencyOptions.forEach(function (item) {
            item.classList.toggle(
                "active",
                item.dataset.value === value
            );
        });

        currencyPicker.classList.remove("open");
        currencyButton.setAttribute(
            "aria-expanded",
            "false"
        );
    }

    currencyButton.addEventListener("click", function (event) {
        event.stopPropagation();

        const opened =
            currencyPicker.classList.toggle("open");

        currencyButton.setAttribute(
            "aria-expanded",
            opened ? "true" : "false"
        );
    });

    currencyOptions.forEach(function (option) {
        option.addEventListener("click", function () {
            setCurrency(option);
        });
    });

    document.addEventListener("click", function (event) {
        if (!currencyPicker.contains(event.target)) {
            currencyPicker.classList.remove("open");

            currencyButton.setAttribute(
                "aria-expanded",
                "false"
            );
        }
    });

    document.addEventListener("keydown", function (event) {
        if (event.key === "Escape") {
            currencyPicker.classList.remove("open");

            currencyButton.setAttribute(
                "aria-expanded",
                "false"
            );
        }
    });

    form.addEventListener("submit", function (event) {
        event.preventDefault();

        if (!validateForm()) {
            focusFirstInvalid();
            return;
        }

        signatureData.value =
            canvas.toDataURL("image/png");

        submitButton.disabled = true;
        submitButton.textContent = "Registrando...";

        form.submit();
    });

    updateDocumentMode();
});
